/** Display label for a citation target (prototype `srcLabel` behaviour). */
const FILE_NAMES: Record<string, string> = {
  conn: "connection.py",
  tconn: "test_connection.py",
  tsock: "test_socketlevel.py",
  log: "1362.bugfix.rst",
};

export function mockSourceLabel(ref: string): string {
  const [kind, a, b] = ref.split(":");
  if (kind === "desc") return "PR description";
  const name = FILE_NAMES[a] ?? a;
  return b ? `${name}:${b.replace("-", "\u2013")}` : name;
}